/* @lc app=leetcode id=2360 lang=kotlin */
class Solution { fun longestCycle(edges: IntArray): Int = (IntArray(edges.size) { -1 } to intArrayOf(-1)).let { (vis, res) -> edges.indices.forEach { i -> if (vis[i] == -1) mutableMapOf<Int, Int>().let { path -> generateSequence(i to 0) { (u, d) -> edges[u].takeIf { it != -1 && vis[it] == -1 }?.let { it to d + 1 } }.onEach { (u, d) -> vis[u] = i.also { path[u] = d } }.last().let { (lastU, lastD) -> edges[lastU].takeIf { it != -1 && vis[it] == i }?.let { next -> res[0] = maxOf(res[0], lastD - path[next]!! + 1) } } } }.run { res[0] } } }